class LiveData<T>(private var value: T) {
    private val observers = mutableListOf<(T) -> Unit>()

    fun observe(observer: (T) -> Unit) {
        observers.add(observer)
        observer(value)
    }

    fun setValue(newValue: T) {
        value = newValue
        observers.forEach { it(value) }
    }

    fun getValue(): T = value
}

