solution_code:
data class Weather(val city: String, val temp: Int, val condition: String)

sealed class WeatherResult {
    data class Success(val weather: Weather) : WeatherResult()
    data class NotFound(val cityName: String) : WeatherResult()
}

fun queryWeather(city: String, data: Map<String, Weather>): WeatherResult {
    val weather = data[city]
    return if (weather != null) {
        WeatherResult.Success(weather)
    } else {
        WeatherResult.NotFound(city)
    }
}

fun findWarmCities(weathers: List<Weather>, minTemp: Int): List<String> {
    return weathers
        .filter { it.temp >= minTemp }
        .sortedByDescending { it.temp }
        .map { it.city }
}
